<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{authRequest,logout,userId}from'../../api/client';import{useRouter}from'vue-router';const router=useRouter(),user=ref<any>(JSON.parse(localStorage.getItem('auth_user')||'{}'));onMounted(async()=>{try{user.value=await authRequest('/api/v1/auth/me')}catch{}});function signout(){logout();router.replace('/home')}</script>
<template><section><div class="page-title"><p class="eyebrow">PROFILE</p><h1>My Profile</h1><p>Account, language and viewing preferences.</p></div><el-card><el-descriptions :column="1" border><el-descriptions-item label="User ID">{{user.id||userId()}}</el-descriptions-item><el-descriptions-item label="Email">{{user.email}}</el-descriptions-item><el-descriptions-item label="昵称">{{user.display_name||'-'}}</el-descriptions-item><el-descriptions-item label="Country">{{user.country||'-'}}</el-descriptions-item><el-descriptions-item label="Language">{{user.language||'-'}}</el-descriptions-item></el-descriptions><el-button class="pay-btn" @click="signout">退出登录</el-button></el-card></section></template>